using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class DestinationSurvey {
 static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var fs=root.Find("Facility_Floor_Guidance_R1").GetComponentsInChildren<MeshFilter>();var l=fs.Single(f=>f.sharedMesh.name.EndsWith("_L"));var r=fs.Single(f=>f.sharedMesh.name.EndsWith("_R"));var lv=l.sharedMesh.vertices;var rv=r.sharedMesh.vertices;if(lv.Length!=rv.Length)throw new Exception("Ribbon samples differ");var center=Enumerable.Range(0,lv.Length/2).Select(i=>V((l.transform.TransformPoint(lv[i*2])+l.transform.TransformPoint(lv[i*2+1])+r.transform.TransformPoint(rv[i*2])+r.transform.TransformPoint(rv[i*2+1]))*.25f)).ToArray();
 var guides=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.transform.IsChildOf(root.Find("Facility_Floor_Guidance_R1"))||f.name.StartsWith("CW_")||f.name.StartsWith("SC_R1")||f.name.StartsWith("SC_Destination")||f.name.StartsWith("T01_C")).Select(f=>new{path=P(f.transform),active=f.gameObject.activeInHierarchy,enabled=f.GetComponent<Renderer>()?.enabled,position=V(f.transform.position),forward=V(f.transform.forward),asset=AssetDatabase.GetAssetPath(f.sharedMesh),materials=f.GetComponent<Renderer>()?.sharedMaterials.Select(m=>m.name).ToArray(),vertices=f.sharedMesh.vertices.Select(v=>V(f.transform.TransformPoint(v))).ToArray(),triangles=f.sharedMesh.triangles}).ToArray();
 var result=new{scene=s.path,centerline=center,guides};var repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));File.WriteAllText(repo+"/SourceAssets/B5_DestinationColors/survey.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{samples=center.Length,first=center.First(),last=center.Last(),guideObjects=guides.Length};}
}
